#!/usr/bin/env bash
# probe_D433.sh — проба пункта D433: проверка возврата читает код 127 как «ещё нет» (аудит B5).
# Результат: условие возврата, чья команда не запускается (код 126/127), названо своей строкой «НЕ ПРОВЕРЕНА», а не «⏳ ещё нет»; `false` даёт ⏳, `true` даёт ✅.
# Проверка результата: bash hooks/tests/fixtures/probe_D433.sh даёт 0
#
# Коды: 0 — желаемое поведение соблюдено; 1 — дефект наблюдён; 2 — рамка не собралась (stderr называет, что).
# Механизм под судом берётся из CLAUDSOUL_REPO (зелёная сторона подставляет копию с починкой);
# страж берёт долг у репозитория по cwd, поэтому фикстура — свой git-репозиторий. HOME подменён.
# Судится ВЫВОД стража: на какой строке назван пункт.
set -uo pipefail
ROOT="$(cd "$(dirname "$0")/../../.." && pwd -P)"
MECH="${CLAUDSOUL_REPO:-$ROOT}"
S="$MECH/scripts/backlog-return-check.sh"
[ -f "$S" ] || { echo "probe_D433: нет $S" >&2; exit 2; }
command -v git >/dev/null 2>&1 || { echo "probe_D433: нужен git" >&2; exit 2; }
T=$(mktemp -d) || { echo "probe_D433: нет временного каталога" >&2; exit 2; }
trap 'rm -rf "$T"' EXIT
R="$T/repo"; mkdir -p "$R" "$T/home"
git -C "$R" init -q 2>/dev/null || { echo "probe_D433: git init не удался" >&2; exit 2; }
MISSING=claudsoul_missing_probe_d433_7429
bash -c "$MISSING" >/dev/null 2>&1; _mrc=$?
[ "$_mrc" -eq 127 ] || { echo "probe_D433: имя $MISSING дало $_mrc, а не 127 — рамка не собралась" >&2; exit 2; }
cat > "$R/BACKLOG.md" <<EOF
# BACKLOG

- ☐ **D901** условие — команда, которой нет
  **Проверка возврата:** \`$MISSING\`
- ☐ **D902** условие ещё не наступило
  **Проверка возврата:** \`false\`
- ☐ **D903** условие наступило
  **Проверка возврата:** \`true\`
EOF
OUT=$(cd "$R" && HOME="$T/home" bash "$S" 2>&1); RC=$?
[ "$RC" -le 1 ] || { echo "probe_D433: страж отказал кодом $RC — рамка не собралась: $OUT" >&2; exit 2; }

# Положительные контроли: ✅ несёт D903, ⏳ несёт D902 — иначе страж не различает и своих штатных исходов.
LOK=$(grep '✅' <<< "$OUT" || true); LWAIT=$(grep '⏳' <<< "$OUT" || true)
grep -q 'D903' <<< "$LOK"   || { echo "probe_D433: контроль — наступившее условие (true) не названо ✅: $OUT" >&2; exit 2; }
grep -q 'D902' <<< "$LWAIT" || { echo "probe_D433: контроль — ненаступившее условие (false) не названо ⏳: $OUT" >&2; exit 2; }

# Суд: D901 не на строке ⏳ и назван строкой про неисполнимость / непроверенность.
L901=$(grep 'D901' <<< "$OUT" || true)
if grep -q '⏳' <<< "$L901"; then
    echo "probe_D433: дефект — неисполнимая команда (rc 127) названа «ещё нет»: $L901" >&2
    exit 1
fi
if grep -qiE 'не проверен|неисполним|сломан' <<< "$L901"; then
    exit 0
fi
echo "probe_D433: дефект — пункт с неисполнимой командой не назван своим исходом: [$L901]" >&2
exit 1
